CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE sessions(id TEXT PRIMARY KEY, state TEXT NOT NULL, title TEXT NOT NULL, metadata_json TEXT NOT NULL, close_mode TEXT, created_at INTEGER NOT NULL, closed_at INTEGER);
CREATE TABLE agent_configs(id TEXT PRIMARY KEY, config_json TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE threads(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), agent_id TEXT NOT NULL, title TEXT NOT NULL, adapter_snapshot_json TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0, owner_task_id TEXT, active_run_id TEXT, latest_checkpoint_id TEXT, blocked_reason TEXT, fork_of_thread_id TEXT, created_at INTEGER NOT NULL);
CREATE TABLE tasks(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), thread_id TEXT NOT NULL REFERENCES threads(id), spec_json TEXT NOT NULL, state TEXT NOT NULL, queue_reason TEXT, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, result_json TEXT, retry_of_task_id TEXT REFERENCES tasks(id), cancel_requested_at INTEGER, wait_json TEXT, resume_input_json TEXT, resume_key TEXT, resume_hash TEXT, attempt_count INTEGER NOT NULL DEFAULT 0, not_before INTEGER NOT NULL DEFAULT 0, error_json TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(session_id,idempotency_key));
CREATE TABLE task_dependencies(task_id TEXT NOT NULL REFERENCES tasks(id), depends_on_task_id TEXT NOT NULL REFERENCES tasks(id), PRIMARY KEY(task_id,depends_on_task_id));
CREATE TABLE runs(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), attempt_no INTEGER NOT NULL, host_instance_id TEXT NOT NULL, expected_revision INTEGER NOT NULL, state TEXT NOT NULL, adapter_snapshot_json TEXT NOT NULL, adapter_run_ref_json TEXT, held_resources_json TEXT NOT NULL, boundary_seq INTEGER, boundary_hash TEXT, boundary_receipt_json TEXT, started_at INTEGER NOT NULL, ended_at INTEGER, error_json TEXT);
CREATE TABLE messages(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), source_key TEXT NOT NULL, source_thread_id TEXT REFERENCES threads(id), target_thread_id TEXT NOT NULL REFERENCES threads(id), target_port TEXT NOT NULL, envelope_json TEXT NOT NULL, state TEXT NOT NULL, target_run_id TEXT REFERENCES runs(id), applied_checkpoint_id TEXT, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(session_id,source_key,idempotency_key));
CREATE TABLE checkpoints(id TEXT PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES threads(id), revision INTEGER NOT NULL, adapter_version TEXT NOT NULL, format_version TEXT NOT NULL, mode TEXT NOT NULL, ref_json TEXT NOT NULL, created_by_run_id TEXT REFERENCES runs(id), created_at INTEGER NOT NULL, UNIQUE(thread_id,revision));
CREATE TABLE artifacts(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), sha256 TEXT NOT NULL, size INTEGER NOT NULL, relative_path TEXT NOT NULL, name TEXT NOT NULL, media_type TEXT NOT NULL, state TEXT NOT NULL, metadata_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE tool_calls(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), run_id TEXT NOT NULL REFERENCES runs(id), tool_name TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, state TEXT NOT NULL, request_json TEXT NOT NULL, result_json TEXT, external_operation_ref_json TEXT, resources_json TEXT NOT NULL, error_json TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(session_id,tool_name,idempotency_key));
CREATE TABLE events(seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, session_id TEXT REFERENCES sessions(id), thread_id TEXT, task_id TEXT, run_id TEXT, type TEXT NOT NULL, payload_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE conversation(seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, session_id TEXT NOT NULL REFERENCES sessions(id), thread_id TEXT NOT NULL REFERENCES threads(id), task_id TEXT REFERENCES tasks(id), run_id TEXT REFERENCES runs(id), role TEXT NOT NULL, content TEXT NOT NULL, metadata_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE resume_receipts(task_id TEXT NOT NULL REFERENCES tasks(id), idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, input_json TEXT NOT NULL, accepted_at INTEGER NOT NULL, PRIMARY KEY(task_id,idempotency_key));
CREATE INDEX tasks_state_created ON tasks(state,created_at);
CREATE INDEX tasks_thread_state ON tasks(thread_id,state);
CREATE INDEX messages_target_state ON messages(target_thread_id,state);
CREATE INDEX events_session_seq ON events(session_id,seq);
CREATE INDEX conversation_thread_seq ON conversation(thread_id,seq);
CREATE INDEX runs_task ON runs(task_id,attempt_no);
CREATE INDEX tools_run_state ON tool_calls(run_id,state);
